<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('expenses');$pageTitle='Receipt Upload';$activeMenu='expense-upload';$errors=[];$selected=(int)($_GET['expense_id']??$_POST['expense_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$expense=(int)($_POST['expense_id']??0);$s=db()->prepare('SELECT * FROM expenses WHERE id=?');$s->execute([$expense]);$erow=$s->fetch();if(!$erow)$errors[]='Expense request not found.';elseif(role_name()==='Staff'&&(int)$erow['requested_by']!==(int)current_user()['id'])$errors[]='You cannot upload to another user\'s expense.';if(empty($_FILES['receipt']['name']))$errors[]='Choose a receipt file.';if(!$errors){$file=$_FILES['receipt'];if($file['error']!==UPLOAD_ERR_OK)$errors[]='Upload failed.';elseif($file['size']>5*1024*1024)$errors[]='File exceeds 5 MB.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','application/pdf'=>'pdf'];if(!isset($allowed[$mime]))$errors[]='Only JPG, PNG and PDF receipts are accepted.';else{$stored=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!is_dir(UPLOAD_PATH))mkdir(UPLOAD_PATH,0775,true);if(move_uploaded_file($file['tmp_name'],UPLOAD_PATH.'/'.$stored)){$i=db()->prepare('INSERT INTO expense_receipts(expense_id,original_name,stored_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?)');$i->execute([$expense,basename($file['name']),$stored,$mime,$file['size'],current_user()['id']]);log_activity('UPLOAD','Expense Receipt','Uploaded receipt for expense '.$erow['expense_code']);flash('success','Receipt uploaded successfully.');redirect('expenses/upload.php?expense_id='.$expense);}else $errors[]='Unable to save the file.';}}}}
if(isset($_GET['delete_receipt'])){verify_csrf();}
$where='';$params=[];if(role_name()==='Staff'){$where='WHERE requested_by=?';$params[]=(int)current_user()['id'];}$s=db()->prepare("SELECT id,expense_code,description FROM expenses $where ORDER BY id DESC");$s->execute($params);$expenses=$s->fetchAll();if($selected && role_name()==='Staff'){ $own=db()->prepare('SELECT COUNT(*) FROM expenses WHERE id=? AND requested_by=?');$own->execute([$selected,current_user()['id']]);if(!(int)$own->fetchColumn()){http_response_code(403);require ROOT_PATH.'/includes/access_denied.php';exit;}}$receipts=[];if($selected){$s=db()->prepare('SELECT er.*,CONCAT(u.first_name," ",u.last_name) uploader FROM expense_receipts er JOIN users u ON u.id=er.uploaded_by WHERE er.expense_id=? ORDER BY er.id DESC');$s->execute([$selected]);$receipts=$s->fetchAll();}require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Receipt Upload</h1><p>Attach supporting evidence to an existing expense request.</p></div></div><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $x):?><li><?=e($x)?></li><?php endforeach;?></ul></div><?php endif;?><div class="row g-3"><div class="col-lg-5"><div class="card-panel"><div class="card-head"><h2 class="section-title">Upload Receipt</h2></div><div class="card-body"><form method="post" enctype="multipart/form-data"><?=csrf_field()?><div class="mb-3"><label class="form-label">Expense Request</label><select class="form-select" name="expense_id" required><option value="">Select expense</option><?php foreach($expenses as $x):?><option value="<?=$x['id']?>" <?=($selected===$x['id'])?'selected':''?>><?=e($x['expense_code'].' — '.$x['description'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Receipt File</label><input class="form-control" type="file" name="receipt" accept="image/jpeg,image/png,application/pdf" required><div class="form-text">JPG, PNG or PDF. Maximum 5 MB.</div></div><button class="btn btn-primary"><i class="fa-solid fa-cloud-arrow-up me-2"></i>Upload</button></form></div></div></div><div class="col-lg-7"><div class="card-panel"><div class="card-head"><h2 class="section-title">Attached Receipts</h2></div><div class="card-body"><?php if(!$selected):?><div class="empty-state">Select an expense to view its receipt attachments.</div><?php elseif(!$receipts):?><div class="empty-state">No receipts attached to this expense.</div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>File</th><th>Type</th><th>Size</th><th>Uploaded By</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($receipts as $r):?><tr><td><?=e($r['original_name'])?></td><td><?=e($r['mime_type'])?></td><td><?=number_format($r['file_size']/1024,1)?> KB</td><td><?=e($r['uploader'])?></td><td><?=e(date('M d, Y',strtotime($r['created_at'])))?></td><td><a target="_blank" class="btn btn-sm btn-light border" href="<?=e(url('assets/uploads/receipts/'.$r['stored_name']))?>"><i class="fa-solid fa-eye"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
